import hashlib,re
def recover_lock(approved,approved_sha256,current,allowed_current_sha256):
    if not isinstance(approved,bytes) or not approved or len(approved)>65536 or b"\x00" in approved:raise ValueError("invalid approved lock bytes")
    if not isinstance(approved_sha256,str) or not re.fullmatch(r"[a-f0-9]{64}",approved_sha256):raise ValueError("invalid approved digest")
    if hashlib.sha256(approved).hexdigest()!=approved_sha256:raise ValueError("approved lock digest mismatch")
    approved.decode("utf8")
    if current is not None:
        if not isinstance(current,bytes) or len(current)>65536:raise ValueError("invalid current lock bytes")
        if current!=approved:
            if not isinstance(allowed_current_sha256,str) or not re.fullmatch(r"[a-f0-9]{64}",allowed_current_sha256):raise FileExistsError("unapproved current lock")
            if hashlib.sha256(current).hexdigest()!=allowed_current_sha256:raise FileExistsError("current lock changed; review required")
    return approved
